from pathlib import Path
import tarfile,hashlib,json
for app in ['customer','customer-service']:
    expected=Path('apps')/app/'out'
    with tarfile.open('.sites/deploy06-artifacts/'+app+'.tar.gz') as tar:
        actual={m.name.removeprefix('./'):m for m in tar.getmembers() if m.isfile() and not Path(m.name).name.startswith('._')}
        for p in expected.rglob('*'):
            if p.is_file():
                key='out/'+p.relative_to(expected).as_posix()
                assert hashlib.sha256(p.read_bytes()).digest()==hashlib.sha256(tar.extractfile(actual[key]).read()).digest(),key
        assert not any('/.env' in k or k.startswith('apps/api/') or k.startswith('.git/') for k in actual)
        print(app+': archive hashes match '+str(sum(p.is_file() for p in expected.rglob('*')))+' export files; no env/backend/git files')
